head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. inputbox_WEF-87_(WSQ-2252).xml 실행한다.- Run inputbox_WEF-87_ (WSQ-2252) .xml.
    //Verify 1. inputbox_WEF-87_(WSQ-2252).xml 실행된다.-inputbox_WEF-87_ (WSQ-2252) .xml is executed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('textbox1').getValue() == '한글 '", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 그리드위의 input박스에 한글을 입력한다.-Type Hangul in the input box above the grid.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('inp_input1').setValue('한글이')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 한글이 정상적으로 입력되어진-Hangul is entered normally.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inp_input1').getValue() == '한글이'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create by Truong.Luu
    //Create date 18-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
